#!/usr/bin/env python3
"""Static controls, generated bytes and clean snapshot checks. Never runs Quartus."""
import argparse
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'tests/restart'))
from prepare_build import prepare, record


def digest(data):
    return hashlib.sha256(data).hexdigest()


def load_registry():
    return json.loads((Path(__file__).with_name('registry.json')).read_text())


def expected_build_id():
    return bytes.fromhex(load_registry()['generated_build_id_hex'])


def profile_spec(profile='q25'):
    """Compiler-specific, committed hardware allow-list. Unknown profiles fail closed."""
    profiles = load_registry()['compiler_profiles']
    if profile not in profiles:
        raise ValueError('Unknown compiler profile: ' + profile)
    return profiles[profile]


def hardware_hashes(root, profile='q25'):
    """Check all recorded hardware/IP/config inputs, not only the edited modules."""
    root = Path(root)
    spec = json.loads(Path(__file__).with_name(profile_spec(profile)['manifest']).read_text())
    actual = {}
    for rel, wanted in spec['files'].items():
        path = root / rel
        if not path.is_file() or path.is_symlink():
            raise ValueError('Missing or symlink hardware input: ' + rel)
        actual[rel] = digest(path.read_bytes())
        if actual[rel] != wanted:
            raise ValueError('Hardware/config differs from ' + profile + ' approved manifest: ' + rel)
    suffixes = {'.v', '.sv', '.vhd', '.vhdl', '.vh', '.svh', '.qsf', '.qpf', '.qip', '.sdc', '.tcl', '.mif', '.hex', '.rom', '.qsys', '.ip', '.sip', '.sopcinfo'}
    excluded = {'tests', 'docs', '.github', '.git', 'db', 'incremental_db', 'output_files', 'old-builds', 'test-builds', '__pycache__'}
    for path in root.rglob('*'):
        rel = path.relative_to(root)
        if path.is_file() and not any(p in excluded for p in rel.parts) and path.suffix.lower() in suffixes:
            if rel.as_posix() not in spec['files'] and rel.as_posix() != 'build_id.v':
                raise ValueError('Unapproved additional hardware/config input: ' + rel.as_posix())
    return actual


def verify_version(text, profile='q17'):
    config = profile_spec(profile)
    pattern = r'\bVersion\s+' + re.escape(config['quartus_version']) + r'\s+Build\s+' + str(config['quartus_build']) + r'\b'
    if not re.search(pattern, text) or not re.search(r'\bLite Edition\b', text):
        raise ValueError('Wrong Quartus version/edition for ' + profile)
    if re.search(r'\b(?:Standard|Pro) Edition\b', text):
        raise ValueError('Mixed or non-Lite Quartus version: ' + profile)
    return {'version': config['quartus_version'], 'build': config['quartus_build'], 'edition': 'Lite', 'compiler_profile': profile}


def write_json(path, data):
    Path(path).write_text(json.dumps(data, indent=2, sort_keys=True) + '\n')


def create(source, output, experiment='R0', overlay=None, evidence=None, profile='q25'):
    reg = load_registry()
    if experiment not in reg['experiments']:
        raise ValueError('Unknown physical experiment: ' + experiment)
    if experiment == 'R0' and (overlay or evidence):
        raise ValueError('R0 cannot contain a physical overlay')
    hardware_hashes(source, profile)
    accepted = None
    if experiment != 'R0':
        from physical.overlays import validate_recipe
        if not overlay or not evidence:
            raise ValueError(experiment + ' evidence gate pending: supply reviewed recipe and complete R0 evidence')
        accepted = validate_recipe(overlay, evidence, experiment, profile=profile)
    # Existing clean-source preparation refuses dirty/unknown source and old databases.
    provenance = prepare(source, output, 'baseline', verified_physical=True)
    output = Path(output).resolve()
    out = output / 'output_files'
    (out / 'closure_diagnostics').mkdir()
    (out / 'build_variant.txt').write_text(experiment + '\n')
    provenance.update({
        'experiment': {'name': experiment, 'kind': reg['experiments'][experiment]['kind'],
                       'hardware_baseline': profile_spec(profile)['hardware_baseline'], 'compiler_profile': profile, 'controlled': True},
        'actual_preparation_timestamp_utc': datetime.now(timezone.utc).isoformat(),
        'generated_input': {'path': 'build_id.v', 'sha256': digest(expected_build_id()),
                            'policy': 'restore exact measured bytes after pre-flow; never change system clock'},
        'hardware_hashes': hardware_hashes(output, profile),
        'compiler_profile': profile,
        'hardware_manifest_sha256': digest(Path(__file__).with_name(profile_spec(profile)['manifest']).read_bytes()),
    })
    from project_assignments import capture
    write_json(out / 'control_project_calls_prepared.json', capture(output))
    if accepted:
        from physical.overlays import materialize
        materialize(output, accepted, evidence)
        provenance['physical_overlay'] = accepted
    (out / 'provenance.json').write_text(json.dumps(provenance, indent=2) + '\n')
    # Replace the generic prepared record before compilation, preserving overlay bytes.
    record(output, 'prepared')
    return provenance


def freeze_generated(root):
    root = Path(root)
    target = root / 'build_id.v'
    if target.is_symlink():
        raise ValueError('Refusing symlink generated input')
    before = digest(target.read_bytes()) if target.exists() else None
    target.write_bytes(expected_build_id())
    out = root / 'output_files'
    write_json(out / 'generated_input_freeze.json', {
        'actual_timestamp_utc': datetime.now(timezone.utc).isoformat(),
        'path': 'build_id.v', 'previous_sha256': before,
        'pinned_sha256': digest(expected_build_id()), 'bytes': len(expected_build_id()),
        'clock_modified': False,
    })


def verify_generated(root):
    if (Path(root) / 'build_id.v').read_bytes() != expected_build_id():
        raise ValueError('Generated build_id.v changed; experiment is invalid')


def stage_inputs(root, phase):
    """Record vendor-expanded calls, reject non-QSF hardware drift and overlays
    beyond the single reviewed factor. Never model vendor defaults as Python.
    """
    from project_assignments import capture
    root = Path(root); out = root / 'output_files'
    verify_generated(root)
    provenance = json.loads((out / 'provenance.json').read_text())
    for rel, wanted in provenance['hardware_hashes'].items():
        # Quartus may serialize its own project settings. Compare its sourced
        # assignment calls against the equivalent control stage below instead.
        if rel in ('Groovy.qsf', 'Groovy.qpf'): continue
        if not (root / rel).is_file() or digest((root / rel).read_bytes()) != wanted:
            raise ValueError('Unexpected hardware/source change at ' + phase + ': ' + rel)
    actual = capture(root)
    write_json(out / ('project_calls_' + phase + '.json'), actual)
    experiment = provenance['experiment']['name']
    if experiment == 'R0':
        control = json.loads((out / 'control_project_calls_prepared.json').read_text()) if phase == 'before_map' else None
        additions = []
    else:
        path = out / 'control_evidence' / ('project_calls_' + phase + '.json')
        if not path.is_file(): raise ValueError('Missing equivalent R0 assignment stage: ' + phase)
        control = json.loads(path.read_text())
        additions = []
        for a in provenance['physical_overlay']['assignments']:
            additions.append(['instance', '-name', a['name'], a['value'], '-to', a['target']] if a['kind'] == 'instance'
                             else ['location', a['value'], '-to', a['target']])
    def policy(events):
        # DUPLICATE_ATOM synthesized names are freshly resolved for each map.
        # Their policy and actual separation have separate mandatory audits.
        return [r for r in events if 'DUPLICATE_ATOM' not in r]
    if control is not None:
        wanted = policy(control['events'])
        observed = policy(actual['events'])
        occurrences = []
        for addition in additions:
            count = observed.count(addition)
            if not count: raise ValueError('Required physical assignment absent at ' + phase)
            # Quartus map serializes sourced calls into the QSF while retaining
            # the source statement. Permit repeated EXACT approved calls only;
            # preserve every other event and its precedence/order.
            occurrences.append({'assignment': addition, 'count': count})
            observed = [row for row in observed if row != addition]
        if observed != wanted:
            write_json(out / ('assignment_difference_' + phase + '.json'), {'expected': wanted, 'actual': policy(actual['events'])})
            raise ValueError('Unapproved effective assignment difference at ' + phase)
    write_json(out / ('input_gate_' + phase + '.json'), {
        'pass': True, 'generated_input_sha256': digest(expected_build_id()),
        'assignment_scope': actual['scope'], 'vendor_defaults_checked_here': False,
        'derived_duplication_policy_requires_fresh_map_and_fitted_audits': True,
        'reviewed_assignment_occurrences': occurrences if control is not None else [],
    })
    record(root, phase)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    sub = p.add_subparsers(dest='command', required=True)
    q = sub.add_parser('prepare')
    q.add_argument('source'); q.add_argument('output'); q.add_argument('experiment', choices=['R0', 'A1', 'D1'])
    q.add_argument('--overlay'); q.add_argument('--evidence')
    q.add_argument('--profile', choices=['q17','q25'], default='q25')
    for name in ['freeze', 'verify-generated', 'verify-hardware']:
        v = sub.add_parser(name); v.add_argument('root')
        if name == 'verify-hardware': v.add_argument('--profile', choices=['q17','q25'], default='q25')
    q = sub.add_parser('stage-inputs'); q.add_argument('root'); q.add_argument('phase', choices=['before_map', 'before_fit'])
    v = sub.add_parser('verify-version'); v.add_argument('file')
    v.add_argument('--profile', choices=['q17','q25'], default='q17')
    a = p.parse_args()
    if a.command == 'prepare':
        create(a.source, a.output, a.experiment, a.overlay, a.evidence, a.profile)
    elif a.command == 'freeze': freeze_generated(a.root)
    elif a.command == 'verify-generated': verify_generated(a.root)
    elif a.command == 'verify-hardware': hardware_hashes(a.root, a.profile)
    elif a.command == 'stage-inputs': stage_inputs(a.root, a.phase)
    else: verify_version(Path(a.file).read_text(), a.profile)


if __name__ == '__main__':
    # Make package imports work for direct invocation from any working directory.
    sys.path.insert(0, str(ROOT / 'tests'))
    main()
